export const getJSONFromURL = async (url: string) => {
    return await (await fetch(url)).json();
};
export const getCSVFromURL = async (url: string) => {
    return await (await fetch(url)).text();
};
export const getImgFromURL = async (path: string) => {
    // if (njslabSandboxStatic.app) { if (njslabSandboxStatic.app.isProduction) { return; } }
    return fetch(`${path}`)
        .then((response: Response) => {
            return response.blob();
        })
        // tslint:disable-next-line:no-any
        .then((d: any) => {
            const img = new Image();
            const objectURL = URL.createObjectURL(d);
            img.src = objectURL;
            img.onload = () => {
                img.crossOrigin = 'anonymous';
                // njslabSandboxStatic.app.imageUtilities.SetData(img);
            };
            return img;
        })
        .catch((err: Error) => {
            //     console.log(err);
        });
};
export const loadSVGFromHTTP = async (path: string) => {
    return fetch(path, { mode: 'no-cors' })
        .then((response: Response) => {
            return response.text();
        }).catch((err: Error) => {
            console.log(err);
        });
}